function localizedReason(locale: WorkspaceLocale, domain: AdminPolicyReasonDomain, value: string): string {
  const normalized = domain === 'dlp' ? value.replace(/^simulation:/, '') : value;
  const known = REASON_GROUP[domain][normalized];
  if (known) return REASON_TEXT[locale][known];
  if (domain === 'dlp' && /^dlp-builtin-(credit-card|iban|social-security-number|api-key|password)$/.test(normalized)) return REASON_TEXT[locale].sensitive;
  if (domain === 'dlp' && /^dlp-(audit|warn-justify|block|require-recipient-encryption|require-approved-space)$/.test(normalized)) return REASON_TEXT[locale].action;
  if (domain === 'backup') return REASON_TEXT[locale].backupFailed;
  const fallback: Readonly<Record<AdminPolicyReasonDomain, ReasonGroup>> = {
    device: 'requirements', 'key-provider': 'unavailable', dlp: 'action', retention: 'retentionActive',
    network: 'deniedByPolicy', audit: 'auditFailed', backup: 'backupFailed',
  };
  return REASON_TEXT[locale][fallback[domain]];
}

export function adminPolicyCopy(locale: WorkspaceLocale): AdminPolicyRenderCopy {
  return {
    ...COPY[locale],
    auditVerificationFailed: AUDIT_FAILURE[locale],
    auditResult: (ok, reason) => COPY[locale].auditResult(ok, localizedReason(locale, 'audit', reason)),
    reason: (domain, value) => localizedReason(locale, domain, value),
    keyProviderClaim: (value) => KEY_PROVIDER_CLAIM_TEXT[locale][value] ?? REASON_TEXT[locale][KEY_PROVIDER_CLAIM[value] ?? 'unavailable'],
    releaseChannel: (value) => CHANNEL_COPY[locale][value],
    finding: (value) => FINDING_COPY[locale][value as keyof typeof FINDING_COPY[typeof locale]] ?? REASON_TEXT[locale].requirements,
    value: (key) => VALUES[locale][key],
    tabs: TABS[locale],
    descriptions: DESCRIPTIONS[locale],
  };
}
export function useAdminPolicyCopy(): AdminPolicyRenderCopy {
  const { locale } = useWorkspaceLocale();
  return adminPolicyCopy(locale);
}
